const items = $input.all();
const results = [];
for (const item of items) {
  const translated = item.json.data?.translations?.[0]?.translatedText || item.json.translatedText || '';
  const sourceText = $('HTTP Extract Text').item.json.ParsedResults?.[0]?.ParsedText || '';
  const webhookData = $('Webhook Document').item.json.body || {};
  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
    body { font-family: Arial, sans-serif; margin: 40px; line-height: 1.6; }
    h1 { color: #2c3e50; }
    .original { background: #f8f9fa; padding: 20px; border-left: 4px solid #3498db; margin: 20px 0; }
    .translated { background: #f0fff0; padding: 20px; border-left: 4px solid #27ae60; margin: 20px 0; }
    .meta { color: #999; font-size: 12px; }
  </style></head><body>
    <h1>Translated Document</h1>
    <p class="meta">Source: ${webhookData.sourceLanguage || 'en'} → Target: ${webhookData.targetLanguage || 'es'} | Translated: ${new Date().toISOString()}</p>
    <h2>Translation</h2><div class="translated">${translated.replace(/\n/g, '<br>')}</div>
    <h2>Original Text</h2><div class="original">${sourceText.substring(0, 3000).replace(/\n/g, '<br>')}</div>
  </body></html>`;
  results.push({
    json: {
      html,
      sourceLanguage: webhookData.sourceLanguage || 'en',
      targetLanguage: webhookData.targetLanguage || 'es',
      wordCount: translated.split(/\s+/).length
    }
  });
}
return results;
